 phPins:[ph([1.17,45.05],"Lascaux"),ph([31.13,29.98],"The pyramids of Giza"),ph([23.73,37.97],"The Parthenon"),ph([103.87,13.41],"Angkor Wat"),ph([78.04,27.17],"The Taj Mahal"),ph([2.17,41.4],"The Sagrada Família"),ph([151.21,-33.86],"Sydney Opera House"),ph([55.27,25.2],"Burj Khalifa")],
