/* =====================================================================================================
   4. Philosophy: big questions and where they were first asked
   ===================================================================================================== */
/* Philosophy follows Philodyssey's voyage through philosophy's eras (Presocratics, Athenians, Hellenistic, Sages,
   Believers and Scholastics, Reformers, Rationalists, Empiricists, Idealists, Rebels, Analytic, Continental,
   Contemporaries), one stop per era and place; the portraits are Philodyssey's (see the photo list at the top). */
const PHIL=[
S({title:"The big questions",view:W,mode:"history",sub:"2026",globe:[60,30,1],
 phPins:[ph([23.72,37.98],"Athens: Socrates"),ph([84.99,24.69],"Bodh Gaya: the Buddha"),ph([116.99,35.6],"Qufu: Confucius"),ph([-4.78,37.88],"Córdoba: Ibn Rushd"),ph([4.9,52.37],"Amsterdam: Descartes"),ph([20.51,54.71],"Königsberg: Kant"),ph([2.35,48.86],"Paris: Simone de Beauvoir"),ph([-71.12,42.37],"Harvard: John Rawls")],
 stat:"What is real? How do we know? How should we live? What is fair?",
 body:"Philosophy means ‘love of wisdom’ in Greek. It asks questions that experiments alone can’t settle, and answers them with reasons anyone can check. This tour follows philosophy’s long voyage, from the ports of ancient Greece, the Ganges and China to Baghdad, Amsterdam, Königsberg, Paris and Harvard.",
 more:"Around 2,500 years ago Confucius, the Buddha and the first Greek philosophers lived within about a century of each other, without knowing of one another. At each stop, look for the thinkers’ portraits on the map, and for a thought experiment: a small imagined story that puts an idea to the test."}),
S({title:"The Presocratics: what is everything made of?",view:[9,33.5,31,43.5],globe:[22,38.5,3.5],card:"left",mode:"history",sub:"bc500",
 pins:[[[27.28,37.53],"Miletus: Thales","point"],[[24.98,40.95],"Abdera: Democritus","point"]],
 phPins:[ph([27.34,37.94],"Ephesus: Heraclitus"),ph([15.155,40.16],"Elea: Parmenides")],
 stat:"Thales of Miletus guessed that everything is made of one thing: water",
 body:"Philosophy began around 600 BC in Greek ports on the coast of today’s Turkey. Thales explained the world through nature instead of stories about gods; his answer was wrong, but his question was new. Then came a quarrel over change: Heraclitus said everything flows, while Parmenides, in Elea in southern Italy, argued that change is only an illusion.",
 more:"These first thinkers are called the Presocratics, ‘before Socrates’. Parmenides’ pupil Zeno backed him with puzzles: to cross a room you must first cross half of it, then half of what is left, and so on for ever. Democritus of Abdera found a way out: tiny, uncuttable átomos moving through empty space."}),
S({title:"Athens: Socrates, Plato and Aristotle",view:[16,34.5,28,41.5],globe:[23,38.5,4],card:"left",mode:"history",sub:"bc400",
 pins:[[[23.722,37.975],"The Agora, Athens","point"],[[22.5,38.48],"Delphi: ‘Know yourself’","point"]],
 phPins:[ph([23.69,38.05],"The Academy: Plato"),ph([23.79,40.53],"Stagira: Aristotle")],
 iconPins:[ic([23.708,37.992],"book")],
 stat:"Do you really know what you think you know?",
 body:"Socrates wrote nothing. He asked people in the Agora, the market square of Athens, simple questions like ‘What is courage?’ until they saw their answers didn’t hold up. His student Plato imagined prisoners in a cave who see only shadows on a wall and take them for the real world; Plato’s student Aristotle studied real things, from octopuses to cities, to find what each is for.",
 more:"Athens sentenced Socrates to death in 399 BC for ‘corrupting the young’; he refused to escape. Plato founded the Academy around 387 BC, which gave us the word ‘academic’. Aristotle, from Stagira in the north, studied there for 20 years, set out the rules of logic (‘All humans are mortal; Socrates is human; so Socrates is mortal’) and tutored the young Alexander the Great."}),
S({title:"The Stoics: what can you control?",view:[-14,28,38,52],globe:[22,40,2.4],card:"left",mode:"history",sub:"100/rom",gfRuler:{a:[23.73,37.98],b:[29.92,31.2]},
 lines:[{coords:[[33.63,34.92],[29,36],[25,37],[23.72,37.98]],kind:"flow"},{coords:[[29.12,37.93],[26,38.5],[21,38.5],[17,39.5],[12.49,41.89]],kind:"flow"}],
 pins:[[[29.92,31.2],"Alexandria: the great library","point"],[[12.49,41.89],"Rome: Seneca","point"],[[16.86,48.11],"Carnuntum: Marcus Aurelius","point"]],
 phPins:[ph([33.63,34.92],"Kition: Zeno"),ph([29.12,37.93],"Hierapolis: Epictetus"),ph([23.72,37.98],"The Stoa of Attalos, Athens")],
 stat:"Some things are up to you, and some are not: worry only about the first",
 body:"After Alexander the Great, Greek ideas spread from Egypt to Afghanistan, and philosophy asked a personal question: how can one person live well in a big, uncertain world? Zeno of Kition taught in a painted porch, the Stoa, in Athens: you can’t control what happens, only how you judge it and respond. His followers were named Stoics after the porch.",
 more:"Rival schools answered differently: Epicurus said a happy life needs only simple pleasures and friends, and Diogenes the Cynic lived in a storage jar to show how little anyone needs. Stoicism spread across the Roman Empire, shaded on this map of AD 100, taught by a former slave, Epictetus, and by an emperor, Marcus Aurelius. Alexandria, about 940 km from Athens (drag the ruler), gathered the books of all these schools in its great library."}),
S({title:"The Ganges: is there a self?",view:[70,13,92,30],globe:[82,23,3.5],card:"left",mode:"history",sub:"bc500",
 pins:[[[83.0,25.32],"Varanasi and Sarnath","point"],[[84.99,24.69],"Bodh Gaya: awakening","point"],[[83.28,27.47],"Lumbini: birth","point"]],
 phPins:[ph([85.44,25.14],"Nalanda"),ph([79.31,16.52],"Nagarjunakonda: Nagarjuna")],
 stat:"‘Tat tvam asi’, ‘you are that’: or is there no fixed self at all?",
 body:"In an Upanishad composed by the Ganges, a father dissolves salt in water and asks his son to find it: it is everywhere, though unseen. Like the salt, he says, the one reality, Brahman, is in everything, and your deepest self is that. The Buddha, who awoke under a tree at Bodh Gaya and first taught at Sarnath, said instead that a person has no fixed self, as a chariot is nothing but its parts.",
 more:"He taught a Middle Way between luxury and starving yourself, and that suffering comes from craving and can end. Around AD 200 Nagarjuna went further: nothing exists on its own; everything depends on other things. His ideas were studied for centuries at Nalanda, a Buddhist university with students from as far as China and Korea; its ruins are a World Heritage Site."}),
S({title:"China: Confucius and the Way",view:[98,22,128,42],globe:[114,34,2.6],card:"left",mode:"history",sub:"bc500",
 pins:[[[112.45,34.62],"Luoyang: the Zhou capital","point"]],
 phPins:[ph([116.99,35.6],"Temple of Confucius, Qufu"),ph([110.87,34.63],"Hangu Pass: Laozi"),ph([115.65,34.41],"Meng: Zhuangzi")],
 stat:"‘Do not do to others what you would not want done to yourself’",
 body:"Confucius (551–479 BC), a teacher from Qufu, said goodness, ren, is learned like a craft: through family love, good manners and practice, anyone can become a ‘noble person’. The Daoists answered: stop trying so hard. Their classic, the Daodejing, praises wu wei, acting without forcing, like water, which yields yet wears away stone.",
 more:"Legend says Laozi wrote it for the keeper of the Hangu Pass before riding west on an ox; historians think several writers made it. Zhuangzi dreamed he was a butterfly, then woke and wondered: was he a man who had dreamed of being a butterfly, or a butterfly now dreaming it was a man? Confucius’ ideas later shaped Korea, Japan and Vietnam too."}),
S({title:"Baghdad to Córdoba: faith and reason",view:[-40,16,70,52],globe:[20,36,1.8],card:"left",mode:"history",sub:"1100",gfRuler:{a:[-4.78,37.88],b:[44.36,33.31]},
 pins:[[[-4.78,37.88],"Córdoba","point"],[[64.42,39.77],"Bukhara: Ibn Sina grew up here","point"]],
 phPins:[ph([44.36,33.31],"Baghdad: al-Farabi"),ph([31.23,30.0],"Fustat, Cairo: Maimonides")],
 iconPins:[ic([44.36,33.31],"book")],
 stat:"Floating in the air, unable to see, hear or feel anything, would you still know you exist?",
 body:"In Baghdad, scholars translated Aristotle and Plato into Arabic, and philosophers such as al-Farabi built on them. Ibn Sina (Avicenna), who grew up near Bukhara, imagined this ‘floating man’ and answered yes: so the self is more than the body. In Córdoba, Ibn Rushd (Averroes) argued that truth cannot contradict truth, so careful reasoning and faith must agree.",
 more:"Moses Maimonides, a Jewish scholar also born in Córdoba, made a similar case in his Guide for the Perplexed, written near Cairo. Córdoba is about 4,400 km from Baghdad (drag the ruler). Ibn Rushd’s commentaries on Aristotle, put into Latin, were so studied in Europe’s new universities that scholars there called him simply ‘the Commentator’; Thomas Aquinas, in Paris, built on them."}),
S({title:"Florence: should a ruler be good?",view:[-14,38,22,55],globe:[5,46,3],card:"left",mode:"history",sub:"1500",
 pins:[[[11.25,43.77],"Florence: Machiavelli","point"]],
 phPins:[ph([-0.58,44.84],"Bordeaux: Montaigne"),ph([-0.13,51.51],"London: Francis Bacon")],
 stat:"Is it better for a ruler to be loved or feared?",
 body:"Niccolò Machiavelli, sacked as an official of the Florentine Republic in 1513, wrote The Prince about how rulers really keep power, not how they ought to. Better to be feared than loved, he said, if you cannot be both, but never hated. Readers still argue: honest realism, or advice for tyrants?",
 more:"Printing made books cheap, and Renaissance thinkers questioned old certainties. In France, Michel de Montaigne wrote essays about himself and asked ‘What do I know?’. In London, Francis Bacon warned that our minds fool us, and said knowledge should be built up from careful observation and experiment."}),
S({title:"Amsterdam: I think, therefore I am",view:[-4,49.5,14,55.5],globe:[5,52,5],card:"left",mode:"history",sub:"1650/ned",
 pins:[[[4.9,52.37],"Amsterdam","point"]],
 phPins:[ph([4.3,52.08],"The Hague: Spinoza"),ph([9.73,52.37],"Hanover: Leibniz")],
 iconPins:[ic([4.49,52.16],"book")],
 stat:"You can doubt everything, except that you are the one doing the doubting",
 body:"René Descartes asked: what if my senses fool me, or I am dreaming right now, or a demon is tricking me? He doubted everything he could. One thing was left: to doubt, he must be thinking, so he must exist. ‘I think, therefore I am.’",
 more:"A Frenchman, he spent some 20 years in the Dutch Republic, shaded on this map of 1650, where printers and thinkers had unusual freedom. Princess Elisabeth of Bohemia, living in The Hague, asked him how a mind with no body could move a body, a question still debated. He, Spinoza and Leibniz are called the Rationalists: they trusted reason more than the senses."}),
S({title:"Edinburgh: what can experience teach us?",view:[-14,44,12,59],globe:[-2,52,4],card:"left",mode:"history",sub:"1715",
 pins:[[[-3.19,55.95],"Edinburgh: Hume","point"]],
 phPins:[ph([-1.26,51.75],"Oxford: John Locke"),ph([-0.08,51.55],"London: Mary Wollstonecraft"),ph([6.14,46.2],"Geneva: Rousseau")],
 stat:"The sun has risen every morning so far. Can you prove it will rise tomorrow?",
 body:"The Empiricists said every idea starts in the senses: John Locke called a newborn’s mind a blank sheet of paper. David Hume of Edinburgh went further. We never see one thing make another happen, only one thing following another, so our trust in cause and effect rests on habit, not proof.",
 more:"Hume also said you cannot get an ‘ought’ from an ‘is’: facts alone never tell you what to do. Their age, the Enlightenment, tried to rebuild knowledge and government on reason and evidence. Jean-Jacques Rousseau of Geneva asked whether civilisation had made people worse, and in London in 1792 Mary Wollstonecraft argued that girls only seem less rational because they are denied the same education as boys."}),
S({title:"Königsberg: what can we know?",view:[5.6,49.5,27.6,58.5],globe:[17,54,4.5],card:"left",mode:"history",sub:"1783",
 pins:[[[8.68,50.11],"Frankfurt: Schopenhauer","point"]],
 phPins:[ph([20.51,54.71],"Kant’s tomb, Kaliningrad"),ph([13.4,52.52],"Berlin: Hegel")],
 stat:"Act only on a rule you could want everyone to follow",
 body:"Immanuel Kant (1724–1804) said the mind is not a mirror: space, time and cause are shapes it gives to everything we experience, so we know the world only as it appears to us. In ethics, he said a rule is right only if you could want everyone to follow it, and people must never be used merely as tools.",
 more:"He hardly ever left Königsberg, then a Prussian port, now Kaliningrad in Russia; his tomb stands beside its cathedral. He said Hume had woken him from his ‘dogmatic slumber’. After him came the Idealists: Hegel, in Berlin, saw history as reason unfolding, and Schopenhauer, in Frankfurt, a reader of the Upanishads, saw a blind will behind everything."}),
S({title:"The Rebels: how should I live?",view:[-12,42,24,59],globe:[6,51,3.5],card:"left",mode:"history",sub:"1850",
 pins:[[[12.57,55.68],"Copenhagen: Kierkegaard","point"],[[6.64,49.75],"Trier: Marx","point"]],
 phPins:[ph([-0.13,51.51],"London: John Stuart Mill"),ph([9.76,46.43],"Sils Maria: Nietzsche")],
 stat:"‘Anxiety is the dizziness of freedom’",
 body:"In the 1800s four thinkers rebelled against grand systems that claimed to explain everyone’s life. Søren Kierkegaard, who strolled the streets of Copenhagen by day and wrote by night, said no theory can choose a life for you: you must choose, and commit. In London, John Stuart Mill argued that people should be free to live as they wish, as long as they harm no one else.",
 more:"Karl Marx, born in Trier, argued that the way people make their living shapes their ideas, not the other way round. Friedrich Nietzsche, walking in the Swiss Alps at Sils Maria, urged people to question the values they had inherited and create their own."}),
S({title:"Vienna: the limits of language",view:[-12,44,24,57],globe:[8,51,3.5],card:"left",mode:"history",sub:"1925",
 pins:[[[16.37,48.21],"Vienna: Wittgenstein","point"]],
 phPins:[ph([0.12,52.2],"Cambridge: Bertrand Russell"),ph([11.59,50.93],"Jena: Frege")],
 stat:"What can words say, and what can’t they?",
 body:"Around 1900 some philosophers took up a new tool, logic: break a thought into its parts, as a chemist breaks a compound into elements. Ludwig Wittgenstein, from Vienna, came to study with Bertrand Russell in Cambridge. He first said language pictures facts; later he said a word’s meaning is the way we use it, like a move in a game.",
 more:"In the 1920s the Vienna Circle met to sweep away any claim that science could not check. Russell described a stopped clock that happens to show the right time: if you trust it, your belief is true and you had a good reason, but do you know the time? In 1963 Edmund Gettier used puzzles like this to show that knowing is more than a lucky true belief."}),
S({title:"Paris: condemned to be free",view:[-14,33,16,53],globe:[2,45,3.5],card:"left",mode:"history",sub:"1950",
 pins:[[[7.85,47.99],"Freiburg: Husserl","point"]],
 phPins:[ph([2.35,48.85],"Paris: Sartre"),ph([3.06,36.75],"Algiers: Camus")],
 stat:"‘Existence comes before essence’: you are not born with a purpose; you make yourself by your choices",
 body:"In Paris after the Second World War, Jean-Paul Sartre said humans have no fixed nature, so we are free, and responsible for who we become; pretending otherwise is ‘bad faith’. Simone de Beauvoir added that freedom is always lived in a situation: ‘One is not born, but rather becomes, a woman’, she wrote in The Second Sex (1949).",
 more:"Albert Camus, who grew up in Algiers, said life has no built-in meaning, yet we can still live it fully, like Sisyphus pushing his rock uphill. Their existentialism grew out of phenomenology, begun by Edmund Husserl in Freiburg: describe experience exactly as it shows up. British philosophers called this whole route ‘Continental’."}),
S({title:"Now explore",view:W,globe:[20,25,1],mode:"history",sub:"2026",
 pins:[[[-71.12,42.37],"Harvard, 1971","point"]],
 phPins:[ph([144.96,-37.81],"Melbourne: Peter Singer"),ph([72.88,19.08],"Mumbai: B. R. Ambedkar"),ph([-84.39,33.75],"Atlanta: W. E. B. Du Bois")],
 stat:"One last thought experiment: the veil of ignorance",
 body:"In 1971 John Rawls of Harvard asked: design a fair society, but without knowing who you will be in it: rich or poor, which country, which body. What rules would you choose? Explore these thinkers, their ideas and their thought experiments further in Philodyssey.",
 more:"Today’s philosophers keep asking what we owe each other. Peter Singer asks why a child drowning in a pond in front of you should matter more than one dying far away. W. E. B. Du Bois and B. R. Ambedkar asked whose voices the old ideas of fairness had left out. The Religions and Literature tours visit the faiths and books that carried many of these ideas."})];

const TOURS={
 art:{name:"Guided tour on art and architecture",short:"Art and architecture",hint:"The oldest cave art, pyramids, the Parthenon, Angkor, Gothic glass, the Great Wave and the world’s tallest towers",steps:ART},
 music:{name:"Guided tour on music",short:"Music",hint:"The first flutes, the kora and the steelpan, Vienna, the blues, tango, reggae, gamelan, Afrobeats and K-pop",steps:MUSIC},
 literature:{name:"Guided tour on literature around the world",short:"Literature",hint:"Gilgamesh, Homer, the first novel, the Nights, Shakespeare, Don Quixote, Gutenberg and Macondo",steps:LIT},
 philosophy:{name:"Guided tour on philosophy",short:"Philosophy",hint:"Thales, Socrates and Plato’s cave, the Stoics, the Upanishads and the Buddha, Confucius and the Dao, Ibn Sina’s floating man, Machiavelli, Descartes, Hume, Kant, Kierkegaard, Wittgenstein, Beauvoir and Rawls’s veil",steps:PHIL}};
const IDS=Object.keys(TOURS);
/* stops with their own map mode use the shared per-stop switch (stopModes); alsoOn keeps the tour running in those modes */
IDS.forEach(id=>{const T=TOURS[id],modes=[...new Set(T.steps.map(s=>s.mode).filter(Boolean))];PS_TOURS[id]={name:T.name,short:T.short,hint:T.hint,map:{mode:"relief"},group:"ideas",col:TL,steps:T.steps,stopModes:modes.length>0,alsoOn:modes}});
/* on the Tours page (the shelf file sets the final order) */
{const o=PS_TOUR_ORDER;IDS.forEach(id=>{const k=o.indexOf(id);if(k>=0)o.splice(k,1)});o.push(...IDS)}
const mine=()=>typeof ps!=="undefined"&&ps&&IDS.includes(ps.tour);
/* a stop with its own map mode and a sub (mode:"history", sub:"1783/ah") is set up as if the tour ran on that map:
   the shared sub switch and key read the tour's map mode, so it is lent the stop's mode for that call only */
{const lend=fn=>function(){try{const T=mine()&&PS_TOURS[ps.tour],S=T&&psSteps()[ps.i];if(S&&S.mode&&S.sub&&S.mode!==T.map.mode){const m0=T.map;T.map=Object.assign({},m0,{mode:S.mode});try{return fn.apply(this,arguments)}finally{T.map=m0}}}catch(e){console.error(e)}return fn.apply(this,arguments)};
 if(typeof psSetSub==="function")psSetSub=lend(psSetSub);if(typeof psKeyInfo==="function")psKeyInfo=lend(psKeyInfo)}

